  let clientJS = `
    (function() {
console.log('START RUN');
      const div = document.getElementById('showtext-time');
      if (!div) {
        return;
      }

      let current = div.textContent.trim();
      let num = parseInt(current, 10);

      if (isNaN(num)) {
        num = 0;
      }

      num += 1;
      div.textContent = num.toString();
      console.log('Counter updated to:', num);
    })();
  `;

  return { clientJS };
}

