  x: parseFloat(div2.style.left),
  y: parseFloat(div2.style.top)
};

const dx = div2data.x - div1data.x;
const dy = div2data.y - div1data.y;

const distance = Math.hypot(dx, dy);
console.log('distance:', distance);

function randMultipleOf10(min, max) {
  const lo = Math.ceil(min / 50);
  const hi = Math.floor(max / 50);
  return (Math.floor(Math.random() * (hi - lo + 1)) + lo) * 50;
}

document.getElementById('showtext_distance').textContent = distance

if(distance <= 10){

    document.getElementById('showtext_time').textContent = document.getElementById('showtext-time').textContent;

    let mark = parseInt(document.getElementById('showtext_mark').textContent);
    mark += 1;
    document.getElementById('showtext_mark').textContent = mark;

    document.getElementById('object2').style.left = randMultipleOf10(0, 200) + 'px';
    document.getElementById('object2').style.top = randMultipleOf10(150, 400) + 'px';

